== ./pools.POST.yml
# POST /api/sheets/{sheetId}/pools — adds a pool to the sheet (body: {name, user}), trimmed. A blank name,
# one already a pool, or a viewer is refused (400) and nothing is stored. Recorded as POOL_ADDED.
validate:
  class: net.officefloor.hq.app.pool.ValidatePool
  next: save
save:
  class: net.officefloor.hq.app.pool.SavePool
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.pool.AuditPoolAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.pool.RespondWithPoolAdded
  govern: [ transaction ]
== ./pools.GET.yml
# GET /api/sheets/{sheetId}/pools — the sheet's pools, in the order they were added, each with its members,
# total share (a retired member's counts as 0.00) and whether it is balanced (exactly 100.00).
respond:
  class: net.officefloor.hq.app.pool.RespondWithPools
  govern: [ readonly-transaction ]
== ./pools/{poolId}/members.POST.yml
# POST /api/sheets/{sheetId}/pools/{poolId}/members — adds a person, or another pool, to a pool with a share
# percent (body: {personId or memberPoolId, share, from, to, user}); from and to are optional dates bounding the
# membership, a to-date before the from-date is refused. A person already in the pool, a pool already a member
# of a pool, one that would contain the pool through any chain, a chain of pools more than three deep, a share
# not more than 0.00 and at most 100.00 with at most two decimals, or a viewer is refused (400) and nothing is
# stored. Recorded as POOL_MEMBER_ADDED.
validate:
  class: net.officefloor.hq.app.pool.ValidateMember
  next: save
save:
  class: net.officefloor.hq.app.pool.SaveMember
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.pool.AuditMemberAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.pool.RespondWithMemberAdded
  govern: [ transaction ]
